    // fisi_core.py 4654
    public const string CALC_EXPLAIN_SUBNET_HANDY = "RECHENWEG SUBNETTING\nAm Beispiel\n192.168.1.50/24\n\nSCHRITT 1: Präfixlänge in\nSubnetzmaske umwandeln\n Die Präfixlänge (die Zahl\n nach dem /) gibt an, wie\n viele Bits von links\n auf 1 gesetzt sind.\n /24 bedeutet: die ersten\n 24 Bit der 32-Bit-\n Subnetzmaske sind 1, der\n Rest ist 0.\n /24, Oktett für Oktett:\n 1. Oktett 11111111 = 255\n 2. Oktett 11111111 = 255\n 3. Oktett 11111111 = 255\n 4. Oktett 00000000 =   0\n -> Subnetzmaske:\n    255.255.255.0\n\nSCHRITT 2: Netzadresse\nberechnen\n Netzadresse = IP-Adresse\n UND Subnetzmaske\n (bitweise UND-\n Verknüpfung: nur wenn\n IP-Adresse und Maske\n an derselben Stelle\n eine 1 haben, bleibt dort\n eine 1 stehen)\n 192.168.1.50 UND\n 255.255.255.0, Oktett für\n Oktett:\n 1. Oktett\n       192 = 11000000\n   UND 255 = 11111111\n  Ergebnis = 11000000\n 2. Oktett\n       168 = 10101000\n   UND 255 = 11111111\n  Ergebnis = 10101000\n 3. Oktett\n         1 = 00000001\n   UND 255 = 11111111\n  Ergebnis = 00000001\n 4. Oktett\n        50 = 00110010\n   UND   0 = 00000000\n  Ergebnis = 00000000\n -> Netzadresse:\n    192.168.1.0\n Liegt die Präfixgrenze\n mitten in einem Oktett,\n zählt dort jedes Bit\n einzeln. Beispiel\n 192.168.1.50/28, im\n 4. Oktett:\n   Adresse (50):  00110010\n   Maske (240):   11110000\n   UND-Ergebnis:  00110000\n   = 48\n -> Netzadresse bei /28:\n    192.168.1.48\n\nSCHRITT 3:\nBroadcast-Adresse\nberechnen\n Wildcard-Maske =\n invertierte Subnetzmaske\n (alle Bits umgedreht):\n 255.255.255.0\n -> 0.0.0.255\n Broadcast-Adresse =\n Netzadresse ODER\n Wildcard-Maske\n (bitweise ODER-\n Verknüpfung: alle\n Hostbits werden\n auf 1 gesetzt)\n Im 4. Oktett bitweise\n (in den Oktetten davor\n ist die Wildcard-Maske 0,\n dort bleibt die\n Netzadresse gleich):\n  Netzadresse:    00000000\n  Wildcard-Maske: 11111111\n  ODER-Ergebnis:  11111111\n  = 255\n -> Broadcast-Adresse:\n    192.168.1.255\n Beispiel 192.168.1.50/28\n von oben, im 4. Oktett:\n  Netzadresse:    00110000\n  (= 48)\n  Wildcard-Maske: 00001111\n  (0.0.0.15)\n  ODER-Ergebnis:  00111111\n  = 63\n -> Broadcast-Adresse bei\n    /28: 192.168.1.63\n\nSCHRITT 4: Nutzbare\nHost-Adressen zählen\n Anzahl aller Adressen\n im Netz\n = 2^(32 - Präfixlänge)\n Bei /24: 2^(32 - 24)\n = 2^8 = 256 Adressen\n Davon sind die\n Netzadresse (192.168.1.0)\n und die Broadcast-Adresse\n (192.168.1.255) nicht als\n Host vergebbar,\n deshalb -2:\n Nutzbare Hosts =\n 2^(32 - Präfixlänge) - 2\n = 256 - 2 = 254\n -> erste Host-Adresse:\n    192.168.1.1\n -> letzte Host-Adresse:\n    192.168.1.254\n Ausnahmen: Bei /31 sind\n beide Adressen nutzbar\n (nur für Punkt-zu-Punkt-\n Verbindungen, RFC 3021).\n /32 ist eine einzelne\n Adresse, ohne Netz- und\n Broadcast-Adresse.\n\nHINWEIS ZU IPv6\n IPv6 kennt keine\n Broadcast-Adresse, daher\n entfällt dort der Abzug\n von 2 Adressen. Gezählt\n werden alle\n 2^(128 - Präfixlänge)\n Adressen (einzelne\n Adressen sind\n reserviert, z. B.\n Subnet-Router-Anycast).";
    // fisi_core.py 4798
    public const string CALC_EXPLAIN_RAID_HANDY = "RECHENWEG RAID\nAm Beispiel 4 Festplatten\nx 1.000 GB\n(Bruttokapazität 4.000 GB)\n\nRAID 0 - Striping (ohne\nRedundanz, min. 2\nFestplatten)\n Die Daten werden ohne\n Redundanz auf alle\n Festplatten verteilt.\n Formel:\n Nutzkapazität =\n Anzahl x Kapazität\n Beispiel:\n 4 x 1.000 GB = 4.000 GB\n nutzbar\n Ausfalltoleranz:\n 0 Festplatten (fällt eine\n aus, sind alle Daten weg)\n\nRAID 1 - Spiegelung\n(Mirroring, min. 2\nFestplatten)\n Die Daten werden 1:1 auf\n alle weiteren Festplatten\n gespiegelt (bei 2\n Festplatten auf die\n zweite).\n Formel:\n Nutzkapazität =\n 1 x Kapazität\n Beispiel:\n 1.000 GB nutzbar\n (bei 4 Festplatten stehen\n nur 1.000 GB\n Nutzkapazität zur\n Verfügung, der Rest ist\n Spiegelung)\n Ausfalltoleranz:\n n-1 Festplatten\n\nRAID 5 - verteilte Parität\n(min. 3 Festplatten)\n Eine Festplatte Kapazität\n wird rechnerisch für\n Paritätsdaten verwendet\n (die Parität selbst liegt\n verteilt auf allen\n Festplatten).\n Formel:\n Nutzkapazität =\n (Anzahl - 1) x Kapazität\n Beispiel:\n (4 - 1) x 1.000 GB\n = 3.000 GB nutzbar\n Ausfalltoleranz:\n 1 Festplatte\n\nRAID 6 - doppelte Parität\n(min. 4 Festplatten)\n Wie RAID 5, aber mit\n doppelter Parität für\n mehr Sicherheit.\n Formel:\n Nutzkapazität =\n (Anzahl - 2) x Kapazität\n Beispiel:\n (4 - 2) x 1.000 GB\n = 2.000 GB nutzbar\n Ausfalltoleranz:\n 2 Festplatten\n\nRAID 10 - Spiegelung +\nStriping (min. 4\nFestplatten,\ngerade Anzahl)\n Je zwei Festplatten\n werden gespiegelt\n (RAID 1), diese\n Spiegelpaare werden\n anschließend im\n Striping-Verfahren\n (RAID 0) zusammengefasst.\n Formel:\n Nutzkapazität =\n (Anzahl / 2) x Kapazität\n Beispiel:\n (4 / 2) x 1.000 GB\n = 2.000 GB nutzbar\n Ausfalltoleranz:\n 1 Festplatte sicher\n (bis zu 2, wenn je\n Spiegelpaar nur eine\n ausfällt)\n\nSPEICHEREFFIZIENZ\n Effizienz =\n Nutzkapazität /\n Bruttokapazität x 100\n Beispiel RAID 5:\n 3.000 GB / 4.000 GB x 100\n = 75 %";
