    // fisi_core.py 5628
    public const string CALC_EXPLAIN_SUBNET_V6 = "RECHENWEG NETZDATEN (IPv6)\nAm Beispiel 2001:db8:abcd:12::1/64\n\nSCHRITT 1: Präfixlänge lesen\n   Eine IPv6-Adresse hat 128 Bit in 8 Hextetten zu je 16 Bit.\n   Die Präfixlänge (die Zahl nach dem /) sagt, wie viele Bits\n   von links zum Netz gehören: /64 = die ersten 4 Hextette.\n\nSCHRITT 2: Netzadresse bestimmen\n   Alle Bits nach dem Präfix auf 0 setzen:\n   2001:db8:abcd:12::1 -> 2001:db8:abcd:12::\n   -> Netzadresse: 2001:db8:abcd:12::/64\n\nSCHRITT 3: Adressen zählen\n   Anzahl Adressen = 2^(128 - Präfixlänge)\n   Bei /64: 2^(128 - 64) = 2^64 = 18.446.744.073.709.551.616\n   Kein Abzug von 2: IPv6 hat keine Broadcast-Adresse.\n   -> erste Adresse: 2001:db8:abcd:12::\n   -> letzte Adresse: 2001:db8:abcd:12:ffff:ffff:ffff:ffff\n   Einzelne Adressen sind reserviert, z. B. die Subnet-Router-\n   Anycast-Adresse (alle Bits der Schnittstellenkennung 0,\n   RFC 4291 2.6.1).\n\nHINWEIS: /64 JE LAN\n   Ein LAN bekommt in der Regel ein /64. Die hinteren 64 Bit\n   sind die Schnittstellenkennung (RFC 4291 2.5.1).\n\nKURZSCHREIBWEISE (RFC 5952) IN 5 REGELN\n   2001:0db8:abcd:0012:0000:0000:0000:0001 -> 2001:db8:abcd:12::1\n   1. Führende Nullen in jedem Hextett weglassen (0db8 -> db8).\n   2. Die längste Folge aus mindestens 2 Null-Hextetten wird\n      zu \"::\". \"::\" darf nur einmal vorkommen.\n   3. Bei zwei gleich langen Folgen wird die erste gekürzt.\n   4. Ein einzelnes Null-Hextett bleibt \"0\", nicht \"::\".\n   5. Die Buchstaben a bis f werden klein geschrieben.";
    // fisi_core.py 5660
    public const string CALC_EXPLAIN_SUBNET_V6_HANDY = "RECHENWEG NETZDATEN (IPv6)\nAm Beispiel\n 2001:db8:abcd:12::1/64\n\nSCHRITT 1: Präfixlänge\nlesen\n IPv6 hat 128 Bit in 8\n Hextetten zu je 16 Bit.\n Die Zahl nach dem / sagt,\n wie viele Bits von links\n zum Netz gehören:\n /64 = die ersten 4\n Hextette.\n\nSCHRITT 2: Netzadresse\nbestimmen\n Alle Bits nach dem Präfix\n auf 0 setzen:\n  2001:db8:abcd:12::1\n  -> 2001:db8:abcd:12::\n -> Netzadresse:\n  2001:db8:abcd:12::/64\n\nSCHRITT 3: Adressen zählen\n Anzahl Adressen\n = 2^(128 - Präfixlänge)\n Bei /64: 2^(128 - 64)\n = 2^64\n = 18.446.744.073.709.551\n  .616\n Kein Abzug von 2: IPv6\n hat keine Broadcast-\n Adresse.\n -> erste Adresse:\n  2001:db8:abcd:12::\n -> letzte Adresse:\n  2001:db8:abcd:12:\n  ffff:ffff:ffff:ffff\n Einzelne Adressen sind\n reserviert, z. B. die\n Subnet-Router-Anycast-\n Adresse (alle Bits der\n Schnittstellenkennung 0,\n RFC 4291 2.6.1).\n\nHINWEIS: /64 JE LAN\n Ein LAN bekommt in der\n Regel ein /64. Die\n hinteren 64 Bit sind die\n Schnittstellenkennung\n (RFC 4291 2.5.1).\n\nKURZSCHREIBWEISE\n(RFC 5952) IN 5 REGELN\n 2001:0db8:abcd:0012:\n 0000:0000:0000:0001\n -> 2001:db8:abcd:12::1\n 1. Führende Nullen in\n jedem Hextett weglassen\n (0db8 -> db8).\n 2. Die längste Folge aus\n mindestens 2 Null-\n Hextetten wird zu \"::\".\n \"::\" darf nur einmal\n vorkommen.\n 3. Bei zwei gleich langen\n Folgen wird die erste\n gekürzt.\n 4. Ein einzelnes Null-\n Hextett bleibt \"0\",\n nicht \"::\".\n 5. Die Buchstaben a bis f\n werden klein geschrieben.";
    // fisi_core.py UPS_TASKS: Titel, Frage, Annahmen (Zahlen "werte" in Usv.cs)
    public static readonly IReadOnlyList<(string, string, string)> UPS_TASK_TEXTS = [("Scheinleistung und Wirkleistung", "Ein Server hat laut Typenschild 800 VA bei einem Leistungsfaktor von 0,9. Wie groß ist die Wirkleistung in W? Welche Nennleistung in VA sollte die USV mindestens haben, wenn die Last höchstens 80 % betragen soll?", "keine."), ("Akku-Kapazität (Beispiel EnerSys)", "Eine USV soll 450 W Last 8 Stunden lang versorgen. Der Wechselrichter hat bei dieser Last einen Wirkungsgrad von 84 %, der Akku-Strang hat 48 V. Wie viel Ah braucht der Strang?", "Kein Alterungszuschlag, volle Nennkapazität nutzbar."), ("Laufzeit eines vorhandenen Akkus", "Eine kleine USV hat 2 Blöcke zu je 12 V und 9 Ah in Reihe. Die Last beträgt 300 W, der Wirkungsgrad 85 %. Wie lange läuft sie mit neuem Akku und am Lebensende (80 % Kapazität)?", "Volle Nennkapazität nutzbar."), ("Passt die USV?", "Angeschlossen sind 1.200 VA bei einem Leistungsfaktor von 0,9. Die USV hat 1.500 VA und 1.000 W Nennleistung. Ist sie nach der 80-%-Regel passend?", "Nur die Leistung wird geprüft, nicht die Laufzeit."), ("Akku mit Alterungszuschlag", "Ein Switch-Schrank braucht 1.000 W für 10 Minuten. Wirkungsgrad 90 %, Strangspannung 48 V, Alterungszuschlag 25 %. Wie viel Wh und Ah braucht der Akku?", "Volle Nennkapazität nutzbar."), ("Wie viele Stränge?", "500 W sollen 30 Minuten überbrückt werden. Wirkungsgrad 80 %, Alterungszuschlag 25 %. Ein Strang besteht aus 2 Blöcken zu je 12 V und 12 Ah in Reihe. Wie viele Stränge braucht man parallel?", "Volle Nennkapazität nutzbar.")];
